-- Class notes synopsis batch 1: Agarita, Agrimony, Alfalfa, Aloe, American Ginseng

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Agarita</strong> is an <strong>antimicrobial</strong> herb used in wound wash preparations; related to <strong>Oregon Grape</strong>, its berberine content provides broad-spectrum <strong>antimicrobial</strong> action.$$ WHERE common_name = 'Agarita';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Agrimony</strong> is an <strong>astringent</strong> herb indicated for <strong>urinary</strong> and <strong>reproductive</strong> health.$$ WHERE common_name = 'Agrimony';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Alfalfa</strong> is a highly <strong>nutritive</strong>, <strong>alterative</strong>, <strong>mineralizing</strong>, <strong>diuretic</strong>, and <strong>lymphatic</strong> herb with a salty taste; rich in <strong>chlorophyll</strong>, <strong>phytosterols</strong>, <strong>inositol</strong>, and <strong>B vitamins</strong> (B1, B2, B3, B5, B6, B9, B12), and is <strong>cardioprotective</strong> and <strong>hypolipidemic</strong>. It is a <strong>blood-building</strong> herb for cold constitution and supports <strong>hormone regulation</strong> and <strong>metabolism</strong>, particularly through estrogen pathways as a legume-family herb. It is a key herb in inositol-rich blends for <strong>PMOS</strong> and <strong>fertility</strong> (with astragalus, licorice, red clover, and kudzu) and appears in Fertili-Tea and Legume Tea for Fertility. For the <strong>thyroid</strong> picture - presenting with moderate <strong>malabsorption</strong>, poor appetite, <strong>nervousness</strong>, weakness, and poor nutritional status - it serves as <strong>anti-inflammatory</strong>, <strong>cardioprotective</strong>, <strong>bone-building</strong>, <strong>hypolipidemic</strong>, and <strong>hormone-nourishing</strong>; used in nourishing blends with <strong>Red Clover</strong> for <strong>thyroid</strong>/<strong>Hashimoto's</strong> cases. It supports <strong>bones</strong>, <strong>hair</strong>, <strong>teeth</strong>, calcium, and potassium stores, and nourishes the <strong>kidney</strong> and <strong>bladder</strong>, balancing fluids and restoring electrolytes. Indicated for <strong>anemia</strong> in <strong>pregnancy</strong>; appears as 3 tbsp in Iron Tonic Syrup. In <strong>liver excess</strong>, it acts as a mineral-rich herb to buffer the blood. Also used in nourishing teas for dry constitution and post-menopausal support (with nettles and lemon balm), as a morning-routine alterative, and topically in a spray for hot spots in pets (with chamomile, burdock, dandelion, calendula, and St. John's Wort). Quality note: must be dried a rich green to be of good quality.$$ WHERE common_name = 'Alfalfa';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Aloe</strong> is a <strong>moistening</strong>, <strong>cooling</strong>, <strong>bitter</strong>, and <strong>astringent</strong> herb that is <strong>anticarcinogenic</strong>, <strong>immunomodulating</strong>, and <strong>alkaline-rich</strong>, making it useful in <strong>cancer</strong> care - paired with chlorophyll as a gentle, initial approach to <strong>inflammation</strong> reduction in <strong>cancer</strong> support. It is best indicated for the <strong>bladder</strong> - <strong>UTI</strong> and <strong>cystitis</strong> - and supportive for the <strong>gut lining</strong>, especially for <strong>heartburn</strong>, taken as aloe juice with electrolytes and a little lime. Topically, <strong>Aloe</strong> is <strong>demulcent</strong>, <strong>emollient</strong>, and <strong>anti-inflammatory</strong> for <strong>burns</strong>, where <strong>Prickly Pear cactus</strong> can substitute; salves shine for <strong>abrasions</strong>. <strong>NO for wound wash on deep wounds - Aloe heals too fast; also avoid introducing oils into open tissue (no salves on open wounds).</strong> As a carrier for vaginal washes, note that oils can change the pH of <strong>mucous tissues</strong> - a wash or sitz bath is the better delivery method.$$ WHERE common_name = 'Aloe';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>American Ginseng</strong> (<em>Panax quinquefolius</em>) is a <strong>warming</strong> and <strong>moistening</strong> <strong>adaptogen</strong> and a key herb for <strong>blood sugar dysregulation</strong>; it improves <strong>insulin sensitivity</strong>, helps lower <strong>cortisol</strong>, is <strong>cardioprotective</strong>, and addresses <strong>hyperlipidemia</strong>. Indicated for low metabolic fire; more mild and energetically neutral than <strong>Asian Ginseng</strong> and possibly less stimulating. Effect onset is 7–10 days. Expensive and overharvested. Dose: tincture 1:5, 2–4 ml TID.$$ WHERE common_name = 'American Ginseng';
